func UploadHandler(w http.ResponseWriter, r *http.Request) {
	// Проверяем, что метод запроса — POST.
	if r.Method != http.MethodPost {
		http.Error(w, "Метод должен быть POST", http.StatusMethodNotAllowed)
		return
	}

	// Проверяем тип содержимого запроса.
	contentType := r.Header.Get("Content-Type")
	if !strings.HasPrefix(contentType, "multipart/form-data") {
		http.Error(w, "Неверный тип содержимого: ожидается multipart/form-data", http.StatusBadRequest)
		return
	}

	// Ограничиваем максимальный размер тела запроса.
	// Это защита от попыток загрузки слишком больших файлов.
	r.Body = http.MaxBytesReader(w, r.Body, maxFileSize)

