 */
public Optional<User> findActive(String login) {
    // Получаем поток из коллекции пользователей
    return users.stream()
        // Фильтруем пользователей, у которых логин совпадает с переданным (без учета регистра)
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Оставляем только тех пользователей, которые:
