{
    for (var i = 0; i < attempts; i++)
    {
        try { return await action(); }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
