// Функция worker представляет собой обработчик задач (воркер).
// Она читает задачи из канала jobs, обрабатывает их и отправляет результаты в канал results.
// Параметр wg используется для синхронизации завершения всех воркеров.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // Деферируем вызов Done(), чтобы гарантировать, что счетчик WaitGroup будет уменьшен
    // после завершения работы воркера, независимо от того, как он завершится.
    defer wg.Done()

    // Цикл range по каналу jobs:
    // - Читает задачи из канала до тех пор, пока канал не будет закрыт.
    // - Переменная j принимает очередную задачу типа Job.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи.
        // Возвращает результат r и возможную ошибку err.
        r, err := process(j)

        // Если при обработке возникла ошибка:
        if err != nil {
            // Логируем ошибку с идентификатором задачи (j.ID) и текстом ошибки.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем эту задачу и переходим к следующей.
            continue
        }

        // Если ошибок нет, отправляем результат r в канал results.
        // Это блокирующая операция: воркер будет ждать, пока кто-то не прочитает значение из channels.
        results <- r
    }
}
