/// Разбирает строку в формате "ключ=значение;ключ=значение" в хеш-мапу.
///
/// # Аргументы
/// * `s` - входная строка, содержащая пары ключ-значение, разделенные точкой с запятой.
///
/// # Возвращаемое значение
/// Хеш-мапа, где ключи — это нижний регистр и обрезанные от пробелов ключи,
/// а значения — обрезанные от пробелов значения.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    // Разбиваем исходную строку по символу ';' на отдельные части (пары ключ-значение)
    s.split(';')
        // Для каждой части пытаемся разделить её на ключ и значение по первому вхождению '='.
        // Если '=' не найдено, элемент будет пропущен (filter_map возвращает None для таких случаев).
        .filter_map(|p| p.split_once('='))
        // Преобразуем каждую найденную пару (ключ, значение):
        // - ключ приводим к нижнему регистру и убираем лишние пробелы по краям
        // - значение просто убираем лишние пробелы по краям
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        // Собираем все обработанные пары в HashMap
        .collect()
}
