/// <summary>
/// Выполняет асинхронное действие с повторными попытками в случае возникновения сетевых ошибок.
/// </summary>
/// <remarks>
/// Метод повторяет выполнение переданного действия до тех пор, пока оно не завершится успешно
/// или не будет исчерпано количество попыток. Повторные попытки выполняются только при возникновении
/// <see cref="HttpRequestException"/>. При каждой неудачной попытке (кроме последней) метод ожидает
/// экспоненциально растущее время задержки: 200 мс, 400 мс, 800 мс и т.д.
/// 
/// Если все попытки завершились исключением <see cref="HttpRequestException"/>, метод бросает
/// последнее возникшее исключение. Если же действие завершилось другим типом исключения,
/// оно пробрасывается немедленно без повторных попыток.
/// </remarks>
/// <param name="action">Асинхронная функция, возвращающая целое число, которую необходимо выполнить.</param>
/// <param name="attempts">Количество попыток выполнения действия. Должно быть положительным целым числом.</param>
/// <returns>
/// Целое число, возвращаемое успешным выполнением действия.
/// </returns>
/// <exception cref="InvalidOperationException">
/// Бросается, если метод достигнет конца цикла без возврата значения (теоретически недостижимый случай).
/// </exception>
/// <exception cref="ArgumentOutOfRangeException">
/// Бросается, если значение параметра <paramref name="attempts"/> меньше или равно нулю.
/// </exception>
/// <exception cref="ArgumentNullException">
/// Бросается, если параметр <paramref name="action"/> равен null.
/// </exception>
/// <exception cref="HttpRequestException">
/// Бросается, если все попытки завершились этим исключением.
/// </exception>
/// <example>
/// <code>
/// // Пример использования:
/// var result = await RetryAsync(async () =>
/// {
///     using var client = new HttpClient();
///     var response = await client.GetAsync("https://api.example.com/data");
///     return (int)response.StatusCode;
/// }, 3);
/// </code>
/// </example>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    if (action == null)
        throw new ArgumentNullException(nameof(action));

    if (attempts <= 0)
        throw new ArgumentOutOfRangeException(nameof(attempts), "Количество попыток должно быть положительным.");

    for (var i = 0; i < attempts; i++)
    {
        try 
        { 
            return await action(); 
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }
    throw new InvalidOperationException("unreachable");
}
