import java.time.Month
import java.time.LocalDate

// Функция для парсинга даты в формате dd/MM/yyyy
fun parse(dateString: String): LocalDate {
    // Разбиваем строку на части по разделителю "/"
    val parts = dateString.split("/")

    // Проверяем, что у нас ровно три части: день, месяц, год
    if (parts.size != 3) {
        throw IllegalArgumentException("Неверный формат даты: ожидается dd/MM/yyyy")
    }

    // Извлекаем день, месяц и год из частей
    val day = parts[0].toInt()       // Первый элемент — день
    val month = parts[1].toInt()     // Второй элемент — месяц
    val year = parts[2].toInt()      // Третий элемент — год

    // Создаём объект LocalDate с указанными значениями
    return LocalDate.of(year, month, day)
}

